module parity_8bit (
    input [7:0] in,
    output out
);

    wire w1, w2, w3, w4, w5, w6;
    wire w7, w8, w9, w10;

    assign w1 = in[1] | in[0];
    assign w2 = ~(in[3] | in[2]);
    assign w3 = in[5] | in[4];
    assign w4 = ~(in[7] | in[6]);

    assign w5 = w1 | w2;
    assign w6 = w3 | w4;

    assign w7 = w5 | w6;
    assign w8 = w7 | w1;
    assign w9 = w8 | w3;
    assign w10 = w9 | w5;

    assign out = w10;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    reg out;

    always @(*) begin
        case (sel)
            2'b00: out = in[0];
            2'b01: out = in[1];
            2'b10: out = in[2];
            2'b11: out = in[3];
            default: out = 1'b0;
        endcase
    end

endmodule

module majority (
    input a, b, c,
    output out
);

wire n_c;
wire c1;
wire c2;
wire d1;
wire d2;
wire d3;

not U0 (n_c, c);
and U1 (c1, a, c);
and U2 (c2, b, c);
or U3 (d1, c1, c2);
and U4 (d2, b, n_c);
and U5 (d3, a, n_c);
or U6 (out, d1, d2, d3);

endmodule

module bin_to_gray (
