module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    wire [3:0] g1, g2, g3, g4;
    wire in0 = in[0];
    wire in1 = in[1];

   assign g1 = in1 | in0;
    assign g2 = in1 & in0;
    assign g3 = in1 & in0;
    assign g4 = in1 & in0;

    always @(*) begin
        case ({in1, in0})
            2'b00: out[2] = 1'b1;
            2'b01: out[3] = 1'b1;
            2'b10: out[0] = 1'b1;
            2'b11: out[1] = 1'b1;
            default: out = 4'b1111;
        endcase
    end

endmodule

