module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg [1:0] current_state;
reg [1:0] next_state;

always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= 2'b00;
    else
        current_state <= next_state;
end

assign state = current_state;

always @(*) begin
    case (current_state)
        2'b00: begin
            if (current_state[0])
                next_state = 2'b01;
            else
                next_state = 2'b00;
        end
        2'b01: begin
            if (current_state[0])
                next_state = 2'b11;
            else
                next_state = 2'b01;
        end
        2'b10: begin
            if (current_state[1])
                next_state = 2'b00;
            else
                next_state = 2'b10;
        end
        2'b11: begin
            if (current_state[1])
                next_state = 2'b00;
            else
                next_state = 2'b11;
        end
        default: next_state = 2'b00;
    endcase
end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg [2:0] state;
    wire q0, q1, q2;
    wire next_q0, next_q1, next_q2;
    wire s1, s2, s3; // MOS output signals

    // State flip-flops (posedge clk)
    always @(posedge clk) begin
        q0 <= state[0];
        q1 <= state[1];
        q2 <= state[2];
    end

    // Next state logic (T-type flip-flop excitation logic)
    always @(*) begin
        next_q0 = state[0] ^ ((~state[2] & ~state[1]) | (state[2] & state[1]));
        next_q1 = state[1] ^ ((~state[0] & ~state[2]) | (state[0] & state[2]));
        next_q2 = state[2] ^ ((~state[1] & ~state[0]) | (state[1] & state[0]));
    end

    // T-input generation logic
    wire t0 = (~state[0] & (~state[2] & ~state[1])) | (state[0] & (state[2] & state[1]));
    wire t1 = (~state[1] & (~state[0] & ~state[2])) | (state[1] & (state[0] & state[2]));
    wire t2 = (~state[2] & (~state[1] & ~state[0])) | (state[2] & (state[1] & state[0]));

    // MOS decoder logic
    assign s1 = (state[0] & state[1]) | (state[2] & state[0]) | (~state[0] & ~state[1] & ~state[2]);
    assign s2 = (state[1] & state[2]) | (state[0] & state[2]) | (~state[0] & ~state[1] & ~state[2]);
    assign s3 = (state[2] & state[0]) | (state[1] & state[0]) | (~state[0] & ~state[1] & ~state[2]);

    // State transition logic
    always @(*) begin
        case ({~q0, ~q1, ~q2})
            2'b000: state = {~s1, ~s2, ~s3};
            default: state = 3'b000;
        endcase
    end

    // Outputs
    assign light = {~s3, ~s2, ~s1};

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

wire clk_1 = ~clk; // Invert clock for NAND gates if needed

// Flip-flops for state bits
S_DFF_PP0 u_ff2 (
    .C(clk_1),
    .D(u_ff1.Q),
    .R(reset),
    .Q(u_ff1.Q)
);

S_DFF_PP0 u_ff0 (
    .C(clk_1),
    .D(u_ff0_q),
    .R(reset),
    .Q(u_ff0.Q)
);

// Next state logic
assign u_ff1_D = (~down_request & u_ff0.Q) | (~up_request & u_ff0.Q & ~u_ff1.Q) | (up_request & ~u_ff0.Q & u_ff1.Q) | (down_request & ~u_ff0.Q & ~u_ff1.Q);

assign u_ff0_q = down_request | (up_request & u_ff1.Q) | (u_ff0.Q & ~u_ff1.Q);

// State output decoder
assign state = (down_request & u_ff1.Q) ? 2'b10 : 
               (up_request & u_ff1.Q) ? 2'b11 : 
               (u_ff0.Q) ? 2'b01 : 2'b00;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    reg [1:0] state_reg;
    wire next_state;

    // DFF PP pop for state register
    wire D_state;
    wire E_state = 1'b1;
    wire R_state = ~reset;

    assign D_state = next_state[0];

    always @(posedge clk) begin
        if (!R_state) begin
            state_reg <= 0;
        end else if (E_state) begin
            state_reg <= {1,0} * D_state;
        end else begin
            state_reg <= next_state;
        end
    end

    // Finite state machine logic
    assign [17] coin_inserted;
    assign [16] item_selected;
    assign next_state = (state_reg & coin_inserted) ? (item_selected) ? 0 : 1 : state_reg;

    // Assign state output
    assign state = state_reg[1:0];

endmodule

