module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    reg gt, eq, lt;
    wire [3:0] a_sel, b_sel;
    wire a3, b3, a2, b2, a1, b1, a0, b0;

    assign a3 = a[3];
    assign b3 = b[3];
    assign a2 = a[2];
    assign b2 = b[2];
    assign a1 = a[1];
    assign b1 = b[1];
    assign a0 = a[0];
    assign b0 = b[0];

    always @(*) begin
        if (a > b) gt = 1'b1;
        else if (b > a) eq = 1'b1;
        else eq = 1'b0;
        if (a > b) lt = 1'b1;
        else if (b > a) lt = 1'b0;
        else lt = 1'b1;
    end

endmodule

