module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

    wire not_sel;
    wire not_in;

    assign not_sel = ~sel[0];
    assign not_in  = ~in;

    // From circuit diagram:
    // out1 = in AND sel[1]
    // out0 = NOT(in AND sel[0]) -> which is NAND(in, sel[0])
    // But the diagram shows two 2-input gates: one AND and one NAND.
    // The AND gate has inputs: in and sel[1] -> output out1
    // The NAND gate has inputs: in and sel[0] -> output out0
    // sel[0] and sel[1] are bits of the 2-bit sel signal.

    assign out1 = in & sel[1];
    assign out0 = ~(in & sel[0]); // This is equivalent to NAND(in, sel[0])

    assign out2 = 1'b0;
    assign out3 = 1'b0;

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);
  wire q0, q1, q2, q3, q4, q5, q6, q7;

  // Flip flops for each bit
  SDFF_PP0 u_ff0(
    .C(clk),
    .D(q1),
    .R(rst),
    .Q(q0)
  );
  SDFF_PP0 u_ff1(
    .C(clk),
    .D(q2 ^ q0),
    .R(rst),
    .Q(q1)
  );
  SDFF_PP0 u_ff2(
    .C(clk),
    .D(q3 ^ q2),
    .R(rst),
    .Q(q2)
  );
  SDFF_PP0 u_ff3(
    .C(clk),
    .D(q4 ^ q3),
    .R(rst),
    .Q(q3)
  );
  SDFF_PP0 u_ff4(
    .C(clk),
    .D(q5 ^ q4),
    .R(rst),
    .Q(q4)
  );
  SDFF_PP0 u_ff5(
    .C(clk),
    .D(q6 ^ q5),
    .R(rst),
    .Q(q5)
  );
  SDFF_PP0 u_ff6(
    .C(clk),
    .D(q7 ^ q6),
    .R(rst),
    .Q(q6)
  );
  SDFF_PP0 u_ff7(
    .C(clk),
    .D(q0 ^ q7),
    .R(rst),
    .Q(q7)
  );

  // Gray code from flip-flops
  assign count[0] = q0;
  assign count[1] = q1;
  assign count[2] = q2;
  assign count[3] = q3;
  assign count[4] = q4;
  assign count[5] = q5;
  assign count[6] = q6;
  assign count[7] = q7;

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] cnt;

always @(posedge clk) begin
    if (rst) begin
        cnt <= 4'b0000;
    end else begin
        cnt <= {cnt[2:0], ~cnt[3]};
    end
end

assign q = cnt;

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);
