  wire [3:0] y_in,y_out[3:0];
  reg [3:0] x_sel,y_sel;
  reg [4:0] temp_sum;
  wire [4:0] final_sum;

  // Demultiplexers for input distribution
  dle x_demux(out_x, {3'b0, x[3:0]}, x);
  dle y_demux(y_out, {3'b0, y[3:0]}, y);

  // Control signals for selecting outputs
  assign x_sel = x;
  assign y_sel = y;

  // Sum generation logic
  assign temp_sum = sum_logic(out_x, y_out);
  assign final_sum = sum(temp_sum);

  // Output assignment
  assign sum = final_sum;

endmodule

