module dle (
  input [3:0] out_bus,
  input [3:0] select,
  input data
);
  assign out_bus[0] = (select == 0) ? data : {1'b0};
  assign out_bus[1] = (select == 1) ? data : {1'b0};
  assign out_bus[2] = (select == 2) ? data : {1'b0};
  assign out_bus[3] = (select == 3) ? data : {1'b0};
endmodule

// Sum logic module
module sum_logic (
  input [3:0] x_in,
  input [3:0] y_in,
  output [4:0] sum_out
);
  assign sum_out = {1'b0} + x_in + y_in;
endmodule

