module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out
);

  wire not_bc, not_ad, not_bd, not_ac, not_ab, not_cd;
  wire not_not_bc, not_not_ad, not_not_bd, not_not_ac, not_not_ab, not_not_cd;
  wire temp1, temp2, temp3, temp4;

  // First layer of NAND gates: NOT for pairs
  assign not_bc = ~(b & c);
  assign not_ad = ~(a & d);
  assign not_bd = ~(b & d);
  assign not_ac = ~(a & c);
  assign not_ab = ~(a & b);
  assign not_cd = ~(c & d);

  // Second layer of NAND gates (acting as inverters)
  assign not_not_bc = ~not_bc; // which is (b & c)
  assign not_not_ad = ~not_ad; // which is (a & d)
  assign not_not_bd = ~not_bd; // which is (b & d)
  assign not_not_ac = ~not_ac; // which is (a & c)
  assign not_not_ab = ~not_ab; // which is (a & b)
  assign not_not_cd = ~not_cd; // which is (c & d)

  // Third layer - combining signals
  assign temp1 = not_not_bc & not_not_ad; // (b & c) & (a & d) = a & b & c & d
  assign temp2 = not_not_bd & not_not_ac; // (b & d) & (a & c) = a & b & c & d
  assign temp3 = not_not_ab & not_not_cd; // (a & b) & (c & d) = a & b & c & d

  // Fourth layer - NAND operations
  assign temp4 = ~(temp1 | temp2 | temp3);

  // Final stage
  assign out = ~temp4; // double negation gives original

endmodule

