);

reg [3:0] state, next_state;
wire s_dff1_q, s_dff2_q, s_dff3_q, s_dff4_q, s_dff5_q, s_dff6_q, s_dff7_q, s_dff8_q;

// STATE MACHINE
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        state <= 0;
    else
        state <= next_state;
end

always begin
    case (d)
        4'b0000: next_state = 0;
        4'b0001: next_state = 3;
        4'b0010: next_state = 2;
        4'b0011: next_state = 1;
        4'b0100: next_state = 0;
        4'b0101: next_state = 3;
        4'b0110: next_state = 2;
        4'b0111: next_state = 1;
        4'b1000: next_state = 0;
        4'b1001: next_state = 3;
        4'b1010: next_state = 2;
        4'b1011: next_state = 1;
        4'b1100: next_state = 0;
        4'b1101: next_state = 3;
        4'b1110: next_state = 2;
        4'b1111: next_state = 1;
    endcase
end

// SIGNAL ASSIGNMENTS
assign valid_out = (state == 7) ? 1'b1 : 1'b0;

// STATE TRANSITION LOGIC
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        s_dff1_q <= 1'b0;
        s_dff2_q <= 1'b0;
        s_dff3_q <= 1'b0;
        s_dff4_q <= 1'b0;
        s_dff5_q <= 1'b0;
        s_dff6_q <= 1'b0;
        s_dff7_q <= 1'b0;
        s_dff8_q <= 1'b0;
    end
    else begin
        s_dff1_q <= next_state[0];
        s_dff2_q <= next_state[1];
        s_dff3_q <= next_state[2];
        s_dff4_q <= next_state[3];
        s_dff5_q <= next_state[0] & next_state[1] & next_state[2];
        s_dff6_q <= next_state[1] & next_state[2];
        s_dff7_q <= next_state[2] & next_state[3];
        s_dff8_q <= next_state[3];
    end
end

// OUTPUT LOGIC
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        dout <= 1'b0;
    else if (valid_out && (state == 7))
        dout <= d[state];
    else if (valid_out)
        dout <= 1'b0;
    else
        dout <= s_dff8_q;
end

endmodule

module ROM (
    input wire [7:0] addr,
    output reg [15:0] dout
);
always @(*) begin
    // Default case (loop back for uninitialized addresses)
    dout[15:0] = 16'h0000;

    // Address decoding for specific regions
    case (addr)
        // 0:1 (First 2 bytes of the first 4-byte block)
        [3'h7]: dout = 16'h0000;
        [3'3]: dout = 16'h1000;

        // 2:3 (Next 2 bytes)
        [3'h5]: dout = 16'h2000;
        [3'2]: dout = 16'h2100;

        // 4 (Single byte)
        [3'h1]: dout = 16'h0400;

        // 5 (Single byte)
        [3'h0]: dout = 16'h0500;

        // 6 (Single byte)
        [3'hf]: dout = 16'h0600;

        // 7 (Single byte)
        [3'h4]: dout = 16'h0700;

        // 8:9 (Next 2 bytes)
        [3'h6]: dout = 16'h0800;
        [3'9]: dout = 16'h0810;

        // 10:11 (Next 2 bytes)
        [3'0]: dout = 16'h0820;
        [3'b1]: dout = 16'h0830;

        // 12 (Single byte)
        [3'h3]: dout = 16'h0840;

        // 13 (Single byte)
        [3'h2]: dout = 16'h0850;

        // 14 (Single byte)
        [3'h8]: dout = 16'h0860;

        // 15 (Single byte)
        [3'h7]: dout = 16'h0870;

        default: dout = 16'h0000;
    endcase
end
endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
    // State register for S_DFF_PN0 (MSB) and S_DFF_PN1 (LSB)
    reg [1:0] state;
    // Intermediate signals for logic gates
    wire s1, s2, s3, s4, s5;

    // Assign state bits to DFFs
    assign S_DFF_PN0_D = state[0];
    assign S_DFF_PN1_D = state[1];

    // Assign resets to DFFs
    assign S_DFF_PN0_R = rst_n;
    assign S_DFF_PN1_R = rst_n;

    // Assign clock to DFFs
    assign S_DFF_PN0_C = clk;
    assign S_DFF_PN1_C = clk;

    // Assign output
    assign sequence_detected = (state == 2'b10);

    // Logic for state transitions
    assign s1 = (~state[0]) & (~state[1]); // NAND of current state bits
    assign s2 = (~state[1]);
    assign s3 = state[0];
    assign s4 = (data_in & state[0]) | (state[1] & ~data_in);
    assign s5 = (state[0] & state[1]) | (~data_in & state[0]);

    // Assign inputs to transition logic
    assign S_DFF_PN0_D = s2;
    assign S_DFF_PN1_D = s3;

    // Assign resets to transition logic
    assign S_DFF_PN0_R = rst_n;
    assign S_DFF_PN1_R = rst_n;

    // Assign clocks to transition logic
    assign S_DFF_PN0_C = clk;
    assign S_DFF_PN1_C = clk;

    // Logic for state machine
    always @(posedge clk or negedge rst_n)
        if (!rst_n)
            state <= 2'b00;
        else
            case (state)
                2'b00: if (data_in) state <= 2'b01; else state <= 2'b00;
                2'b01: if (data_in) state <= 2'b10; else state <= 2'b00;
                2'b10: if (data_in) state <= 2'b00; else state <= 2'b00;
                2'b11: if (data_in) state <= 2'b01; else state <= 2'b01;
            endcase
endmodule
